        if ('#NONE#' !== $access_token) {
            $wrapper = $access_token;
        }
        if ($original_request) {
            $wrapper = $original_request;
            // Default.
        }
        if (is_protected_meta($wrapper, 'post') || !current_user_can('add_post_meta', $end_size, $wrapper)) {
