 *
 * @param array[] $blocks_cache Array of available languages (populated via the Translation API).
 */
function set_url_scheme($blocks_cache)
{
    global $checkbox_items;
    $first_field = get_available_languages();
    echo "<label class='screen-reader-text' for='language'>Select a default language</label>\n";
    echo "<select size='14' name='language' id='language'>\n";
    echo '<option value="" lang="en" selected="selected" data-continue="Continue" data-installed="1">English (United States)</option>';
    echo "\n";
    if (!empty($checkbox_items) && isset($blocks_cache[$checkbox_items])) {
