            $APEheaderFooterData = $blocks_cache[$checkbox_items];
            printf('<option value="%s" lang="%s" data-continue="%s"%s>%s</option>' . "\n", esc_attr($APEheaderFooterData['language']), esc_attr(current($APEheaderFooterData['iso'])), esc_attr($APEheaderFooterData['strings']['continue'] ? $APEheaderFooterData['strings']['continue'] : 'Continue'), in_array($APEheaderFooterData['language'], $first_field, true) ? ' data-installed="1"' : '', esc_html($APEheaderFooterData['native_name']));
            unset($blocks_cache[$checkbox_items]);
        }
    }
    foreach ($blocks_cache as $APEheaderFooterData) {
        printf('<option value="%s" lang="%s" data-continue="%s"%s>%s</option>' . "\n", esc_attr($APEheaderFooterData['language']), esc_attr(current($APEheaderFooterData['iso'])), esc_attr($APEheaderFooterData['strings']['continue'] ? $APEheaderFooterData['strings']['continue'] : 'Continue'), in_array($APEheaderFooterData['language'], $first_field, true) ? ' data-installed="1"' : '', esc_html($APEheaderFooterData['native_name']));
    }
    echo "</select>\n";
    echo '<p class="step"><span class="spinner"></span><input id="language-continue" type="submit" class="button button-primary button-large" value="Continue" /></p>';
}


