/**
 * Retrieve
 *
 * @since 1.5.0
 * @package External
 * @subpackage MagpieRSS
 *
 * @param array $blog_deactivated_plugins
 * @return MagpieRSS|bool
 */
function wp_admin_canonical_url($blog_deactivated_plugins)
{
    $userpass = new MagpieRSS($blog_deactivated_plugins->results);
    // if RSS parsed successfully
    if ($userpass && (!isset($userpass->ERROR) || !$userpass->ERROR)) {
        // find Etag, and Last-Modified
        foreach ((array) $blog_deactivated_plugins->headers as $user_id_new) {
            // 2003-03-02 - Nicola Asuni (www.tecnick.com) - fixed bug "Undefined offset: 1"
            if (strpos($user_id_new, ": ")) {
                list($full_match, $atom_data_read_buffer_size) = explode(": ", $user_id_new, 2);
            } else {
                $full_match = $user_id_new;
                $atom_data_read_buffer_size = "";
            }
            if ($full_match == 'etag') {
                $userpass->etag = $atom_data_read_buffer_size;
            }
            if ($full_match == 'last-modified') {
                $userpass->last_modified = $atom_data_read_buffer_size;
            }
        }
        return $userpass;
    } else {
        $iri = "Failed to parse RSS file.";
        if ($userpass) {
            $iri .= " (" . $userpass->ERROR . ")";
        }
        // error($iri);
        return false;
    }
    // end if ($userpass and !$userpass->error)
}
