/**
 * Gets the theme support arguments passed when registering that support.
 *
 * Example usage:
 *
 *     mt_supportedMethods( 'custom-logo' );
 *     mt_supportedMethods( 'custom-header', 'width' );
 *
 * @since 3.1.0
 * @since 5.3.0 Formalized the existing and already documented `...$default_help` parameter
 *              by adding it to the function signature.
 *
 * @global array $nicename__in
 *
 * @param string $outputLength The feature to check. See add_theme_support() for the list
 *                        of possible values.
 * @param mixed  ...$default_help Optional extra arguments to be checked against certain features.
 * @return mixed The array of extra arguments or the value for the registered feature.
 */
function mt_supportedMethods($outputLength, ...$default_help)
{
    global $nicename__in;
    if (!isset($nicename__in[$outputLength])) {
        return false;
    }
    if (!$default_help) {
        return $nicename__in[$outputLength];
    }
    switch ($outputLength) {
        case 'custom-logo':
        case 'custom-header':
        case 'custom-background':
            if (isset($nicename__in[$outputLength][0][$default_help[0]])) {
                return $nicename__in[$outputLength][0][$default_help[0]];
            }
            return false;
        default:
            return $nicename__in[$outputLength];
    }
}


